#!/usr/bin/env python3
"""Check explicit budget outputs and test-point source diagnostics."""
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import time

ROOT=Path(__file__).resolve().parent
CASE=Path(os.environ['SWAN_AUDIT_REPOSITORY']) / 'examples/quick_test'

def main():
    while True:
        try:
            data=json.loads((ROOT/'prototype3.json').read_text())
            if 'time_reduction_percent' in data:break
        except (FileNotFoundError,json.JSONDecodeError):pass
        time.sleep(2)
    base=(CASE/'quick_test.swn').read_text()
    decks={
      'requested-budget':base.replace('XP YP DEPTH HSIGN TM01 DIR','XP YP DEPTH HSIGN TM01 DIR GENW DISW DISSU DISB'),
      'test-point':base.replace('\nCOMPUTE\n',"\nTEST 1 0 POINTS XY 1000.0 500.0 S1D 'source_diagnostics.spc'\nCOMPUTE\n"),
    }
    result={}
    for name,deck in decks.items():
        runs={}
        for build in ['serial','candidate3']:
            p=ROOT/'budget-contract'/name/build;p.mkdir(parents=True)
            (p/'INPUT').write_text(deck);shutil.copy2(CASE/'bottom.bot',p/'bottom.bot')
            env=os.environ.copy();env.update(OMP_NUM_THREADS='1',OMP_DYNAMIC='FALSE')
            with (p/'screen.log').open('w') as log:
                subprocess.run([str(ROOT/build/'bin/swan.exe')],cwd=p,env=env,stdout=log,stderr=subprocess.STDOUT,check=True)
            assert (p/'norm_end').is_file(),p
            outputs=['quick_test_hs.blk','quick_test_center.tbl']
            if name=='test-point':outputs.append('source_diagnostics.spc')
            runs[build]={o:hashlib.sha256((p/o).read_bytes()).hexdigest() for o in outputs}
        if name=='requested-budget':
            lines=(ROOT/'budget-contract'/name/'candidate3/quick_test_center.tbl').read_text().splitlines()
            nums=[float(v) for l in lines if l.strip() and not l.lstrip().startswith('%') for v in l.split()]
            assert any(v!=0 for v in nums[-4:]),nums
        result[name]={'sha256':runs,'byte_identical':runs['serial']==runs['candidate3']}
        assert result[name]['byte_identical'],name
    (ROOT/'budget-contract.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result,indent=2))

if __name__=='__main__':main()
